const depClone=o=>JSON.parse(JSON.stringify(o)),depEl=id=>document.getElementById(id),depEsc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
