function depSeedUnits(){return DEPLOYMENT_SEED.units.map(source=>{const u=depClone(source);if(u.anchorId){const item=conceptItems.find(i=>i.id===u.anchorId),f=DATA.features.find(f=>f.id===u.anchorId),anchor=item?.world||f?.world;if(anchor){u.position=[anchor[0],.3,anchor[2]];if(u.distribution&&item){const b=item.bbox,x0=(b[1]-760)*1.4,x1=(b[3]-760)*1.4,z0=(1000-b[2])*1.4,z1=(1000-b[0])*1.4,k=u.distribution.index/u.distribution.count*4,side=Math.floor(k),t=k-side,inset=u.distribution.kind==='perimeter-inner'?14:4,pts=[[x0+inset,z0+inset],[x1-inset,z0+inset],[x1-inset,z1-inset],[x0+inset,z1-inset]],a=pts[side],bb=pts[(side+1)%4];u.position=[a[0]+(bb[0]-a[0])*t,.3,a[1]+(bb[1]-a[1])*t]}if(u.offset){u.position[0]+=u.offset[0];u.position[2]+=u.offset[2]}u.position=depVacantSeedPosition(u.position,u.type)}}return u})}
function depVacantSeedPosition(p,type){ensureWalkPhysics();const radius=({machan:3.4,morcha:4.7,qrt:5,patrol:5,ambulance:5,fire:6,naka:8})[type]||1.3;function clear(x,z){const reach=Math.ceil(radius/WALK_CELL)+1,ix=Math.floor(x/WALK_CELL),iz=Math.floor(z/WALK_CELL),seen=new Set();for(let a=-reach;a<=reach;a++)for(let b=-reach;b<=reach;b++)for(const wall of walkGrid.get((ix+a)+','+(iz+b))||[]){if(seen.has(wall))continue;seen.add(wall);if(wall.bottom<4&&wall.top>.55&&circleHitsBox(wall,x,z,radius))return false}return true}if(clear(p[0],p[2]))return p;for(let r=4;r<=48;r+=4)for(let i=0;i<16;i++){const x=p[0]+Math.cos(i*Math.PI/8)*r,z=p[2]+Math.sin(i*Math.PI/8)*r;if(clear(x,z))return[x,.3,z]}return p}
function depValidate(data){if(!data||!Array.isArray(data.units)||data.units.length>3000)throw Error('Deployment JSON must contain at most 3000 units.');const seen=new Set();return data.units.map(v=>{if(!v||typeof v.id!=='string'||seen.has(v.id)||!DEP_TYPES[v.type])throw Error('Duplicate ID or invalid duty type.');seen.add(v.id);const u=depClone(v);u.title=String(u.title||u.id).slice(0,180);u.notes=String(u.notes||'').slice(0,5000);u.enabled=u.enabled!==false;u.scale=Math.max(.3,Math.min(5,+u.scale||1));u.speed=Math.max(.2,Math.min(35,+u.speed||7));u.rotation=+u.rotation||0;if(u.position!==null&&(!Array.isArray(u.position)||u.position.length!==3||u.position.some(n=>!Number.isFinite(n)||Math.abs(n)>20000)))throw Error('Invalid position.');u.route=Array.isArray(u.route)?u.route.slice(0,500):[];if(u.route.some(p=>!Array.isArray(p)||p.length!==3||p.some(n=>!Number.isFinite(n)||Math.abs(n)>20000)))throw Error('Invalid route.');u.shifts=u.shifts||{};for(const[k,s]of Object.entries(u.shifts)){if(!DEP_SHIFT[k])throw Error('Unknown shift.');for(const f of['force','female','incharge','extra'])if(s[f]!=null&&(!Number.isInteger(s[f])||s[f]<0||s[f]>10000))throw Error('Strength must be a whole number or blank.');if(s.force!=null&&s.female!=null&&s.female>s.force)throw Error('Women are included in main force and cannot exceed it.')}u.personnel=Array.isArray(u.personnel)?u.personnel.slice(0,500):[];return u})}
