function depOpen(id){if(typeof depDutyCard!=='undefined')depDutyCard.hidden=true;if(conceptMode)go('top');if(id)depSelected=id;depPanel.hidden=false;document.getElementById('selection').style.display='none';depRefreshList();depEditor()}
