function depEffective(u){return u.shifts?.[depShift]||u.shifts?.combined||null}
function depApplicable(u){return u.enabled&&!depTypeHidden.has(u.type)&&!!depEffective(u)}
function depTotals(units,shift){const t={force:0,incharge:0,extra:0,female:0,unknown:0,records:0};for(const u of units){if(!u.enabled||u.isPersonnelMarker)continue;const s=u.shifts[shift];if(!s)continue;t.records++;for(const k of['force','incharge','extra','female'])if(s[k]!=null)t[k]+=s[k];if(s.force==null||s.incharge==null)t.unknown++}return t}
function depSummary(){const t=depTotals(depUnits,depShift),combined=depUnits.filter(u=>u.shifts.combined&&!u.shifts[depShift]).length;depEl('depSummary').textContent=`${depUnits.length} records · ${depUnits.filter(u=>!u.position).length} unplaced. ${DEP_SHIFT[depShift]} known row subtotals: main ${t.force} (women ${t.female} included) + incharge ${t.incharge} + extra ${t.extra}. ${t.unknown} rows have unknown counts. ${depShift==='combined'?'':combined+' shared/unspecified rows are excluded from this shift subtotal.'}`}
function depRefreshList(){const q=depEl('depSearch').value.toLowerCase(),type=depEl('depFilter').value,list=depEl('depList');list.replaceChildren();for(const u of depUnits.filter(u=>(!type||u.type===type)&&[u.title,u.id,u.ground,...u.personnel.map(p=>p.name)].join(' ').toLowerCase().includes(q))){const b=document.createElement('button'),t=document.createElement('span'),badge=document.createElement('small');b.dataset.id=u.id;b.className=u.id===depSelected?'selected':'';t.textContent=u.title;badge.textContent=u.position?'●':'Unplaced';b.append(t,badge);b.onclick=()=>{depSelected=u.id;depEditor();depRefreshList();depEl('depEditor').scrollIntoView({block:'nearest'});dirty=true};list.append(b)}depSummary()}
function depRowShift(k,s={}){return `<fieldset><legend>${DEP_SHIFT[k]}</legend><div class="dep-grid">${[['force','Main force'],['female','Women (included)'],['incharge','Incharge count (separate)'],['extra','Extra staff']].map(([f,l])=>`<label>${l}<input type="number" min="0" max="10000" data-shift="${k}" data-field="${f}" value="${s[f]??''}"></label>`).join('')}</div>${[['inchargeText','Incharge rank / allocation'],['extraText','Extra staff description'],['start','Duty start'],['end','Duty end'],['notes','Shift notes']].map(([f,l])=>`<label>${l}<input ${['start','end'].includes(f)?'type="time"':''} data-shift="${k}" data-field="${f}" value="${depEsc(s[f])}"></label>`).join('')}</fieldset>`}
function depEditor(){const u=depUnits.find(u=>u.id===depSelected),ed=depEl('depEditor');if(!u){depPanel.classList.remove('editing');ed.hidden=true;depEl('depList').style.maxHeight='210px';return}ed.hidden=false;depEl('depList').style.maxHeight='100px';ed.innerHTML=`<h3>${depEsc(u.title)}</h3><div class="dep-muted">${depEsc(u.id)} · ${u.isPersonnelMarker?'Individual included within parent strength':'Editable duty point / object'}</div>${!u.position?'<div class="dep-plan-note">Unplaced: choose Place on model. Location is not confirmed.</div>':''}<div class="dep-plan-note">${Object.entries(u.shifts).map(([k,v])=>depEsc(DEP_SHIFT[k])+': main '+(v.force??'?')+' + incharge '+(v.incharge??'?')+' + extra '+(v.extra??'?')).join('<br>')}</div><label>Name / title<input id="depName" value="${depEsc(u.title)}"></label><div class="dep-grid"><label>Model / duty type<select id="depType">${Object.entries(DEP_TYPES).map(([k,v])=>`<option value="${k}" ${u.type===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Ground / zone<input id="depGround" value="${depEsc(u.ground)}"></label></div><label class="dep-check"><input id="depEnabled" type="checkbox" ${u.enabled?'checked':''}>Duty enabled</label><div class="dep-grid three">${['X','Y','Z'].map((f,i)=>`<label>${f==='Y'?'Height Y':f}<input id="dep${f}" type="number" step=".1" value="${u.position?u.position[i].toFixed(2):''}"></label>`).join('')}</div><div class="dep-grid"><label>Rotation degrees<input id="depAngle" type="number" value="${Math.round(u.rotation*180/Math.PI)}"></label><label>Model scale<input id="depScale" type="number" min=".3" max="5" step=".1" value="${u.scale}"></label></div><div class="dep-mini-actions"><button id="depLocate">Locate</button><button id="depPlace">Place / shift on model</button><button id="depUnplace">Unplace</button></div><label>Point notes<textarea id="depNotes" rows="3">${depEsc(u.notes)}</textarea></label><details><summary>Shift strength and duty timing</summary><p class="dep-muted">Blank means unspecified. Incharge and extras are separate. Women and armed OR are already within their main-force counts.</p>${Object.keys(DEP_SHIFT).map(k=>depRowShift(k,u.shifts[k])).join('')}</details><label>Assigned officers / personnel</label><p class="dep-muted">One per line: Name | Rank | Role | Shift | Contact. Assignments do not add to planned strength automatically.</p><textarea id="depPersonnel" rows="4">${depEsc(u.personnel.map(p=>[p.name,p.rank,p.role,p.shift,p.contact].join(' | ')).join('\n'))}</textarea><button id="depStaffMarkers">Create individual staff icons</button><fieldset><legend>Movement route</legend><p>${u.route.length} points · ${u.route.length>1?'assigned':'no route assigned'}</p><div class="dep-grid"><label>Speed (model units/s)<input id="depSpeed" type="number" min=".2" max="35" step=".5" value="${u.speed}"></label><label>Route mode<select id="depRouteMode"><option value="pingpong" ${u.routeMode!=='loop'?'selected':''}>Return along route</option><option value="loop" ${u.routeMode==='loop'?'selected':''}>Closed loop</option></select></label></div><div class="dep-mini-actions"><button id="depDrawRoute">Draw route on model</button><button id="depClearRoute">Clear route</button></div><p class="dep-muted">Riders use bikes; QRT and patrol use cars. A closed loop connects the last point to the first.</p></fieldset><div class="dep-mini-actions"><button id="depSave" class="primary">Save changes</button><button id="depDuplicate">Duplicate</button><button id="depDelete" class="danger">Delete duty / object</button></div>`;
depSimplifyEditor();depEl('depSave').onclick=depSaveButton;depEl('depPlace').onclick=()=>{if(depSaveEditor())depBeginPick('place')};depEl('depLocate').onclick=()=>{if(!u.position){depBeginPick('place');return}setConcept(false);exitNavigation();pandalInterior=false;target=[...(depPose(u)?.p||u.position)];target[1]+=3;distance=70;topView=false;elevation=.6;yaw=.4;anim=null;depPanel.hidden=true;dirty=true;sceneEl.scrollIntoView({block:'start'})};depEl('depUnplace').onclick=()=>{depUndoPush();u.position=null;depPersist();depRefreshList();depEditor()};depEl('depDrawRoute').onclick=()=>{if(depSaveEditor())depBeginPick('route')};depEl('depClearRoute').onclick=()=>{depUndoPush();u.route=[];depPersist();depEditor()};depEl('depDuplicate').onclick=()=>{if(!depSaveEditor())return;depUndoPush();const v=depClone(u);v.id='D-'+Date.now().toString(36);v.title+=' · copy';if(v.position){v.position[0]+=6;v.position[2]+=6}v.route=[];depUnits.push(v);depSelected=v.id;depPersist();depRefreshList();depEditor()};depEl('depDelete').onclick=()=>{if(depFlow&&u.id===depFlow.id){depCancelDraft();return}depUndoPush();depUnits=depUnits.filter(v=>v.id!==u.id&&v.parentId!==u.id);depSelected=null;depPersist();depRefreshList();depEditor()};depEl('depStaffMarkers').onclick=()=>{if(!depSaveEditor())return;depUndoPush();for(const[i,p]of u.personnel.entries()){if(depUnits.some(v=>v.parentId===u.id&&v.personIndex===i))continue;const v={id:'STAFF-'+Date.now().toString(36)+'-'+i,title:p.name||'Assigned officer',type:'officer',position:u.position?[u.position[0]+(i%5)*2,u.position[1],u.position[2]+5+Math.floor(i/5)*2]:null,ground:u.ground,rotation:u.rotation,scale:1,enabled:true,speed:4,route:[],routeMode:'pingpong',notes:'Included in parent duty strength: '+u.title,parentId:u.id,personIndex:i,isPersonnelMarker:true,personnel:[p],shifts:{[DEP_SHIFT[p.shift]?p.shift:'combined']:{force:/(incharge|इंचार्ज|^ic$)/i.test(p.role)?0:1,incharge:/(incharge|इंचार्ज|^ic$)/i.test(p.role)?1:0,extra:0,female:null}}};depUnits.push(v)}depPersist();depRefreshList();depEditor()}}
function depSaveEditor(){depSyncSimpleOfficer();const u=depUnits.find(u=>u.id===depSelected);if(!u)return false;const copy=depClone(u);copy.title=depEl('depName').value.trim()||u.title;copy.type=depEl('depType').value;copy.ground=depEl('depGround').value;copy.location=depEl('depSimpleLocation')?.value.trim()||'';copy.enabled=depEl('depEnabled').checked;copy.rotation=(+depEl('depAngle').value||0)*Math.PI/180;copy.scale=+depEl('depScale').value||1;copy.speed=+depEl('depSpeed').value||7;copy.routeMode=depEl('depRouteMode').value;copy.notes=depEl('depNotes').value;const p=['depX','depY','depZ'].map(id=>depEl(id).value.trim());if(p.every(v=>v!==''))depMoveUnit(copy,p.map(Number));else if(p.some(v=>v!=='')){depEl('depStatus').textContent='Enter all X, Y, Z coordinates or use Place on model.';return false}copy.shifts={};for(const k of Object.keys(DEP_SHIFT)){const s={};for(const input of depEl('depEditor').querySelectorAll('[data-shift="'+k+'"]')){const f=input.dataset.field;s[f]=['force','female','incharge','extra'].includes(f)?input.value===''?null:Number(input.value):input.value}if(Object.values(s).some(v=>v!==null&&v!==''))copy.shifts[k]=s}copy.personnel=depEl('depPersonnel').value.split('\n').filter(s=>s.trim()).map(line=>{const[name='',rank='',role='',shift='',contact='']=line.split('|').map(s=>s.trim());return{name,rank,role,shift,contact}});try{depValidate({units:[copy]})}catch(e){depEl('depStatus').textContent=e.message;return false}depUndoPush();Object.assign(u,copy);depUnits=depUnits.filter(v=>v.parentId!==u.id||v.personIndex<u.personnel.length);for(const child of depUnits.filter(v=>v.parentId===u.id)){const person=u.personnel[child.personIndex];child.title=person.name||'Assigned officer';child.personnel=[person];child.shifts={[DEP_SHIFT[person.shift]?person.shift:'combined']:{force:/(incharge|इंचार्ज|^ic$)/i.test(person.role)?0:1,incharge:/(incharge|इंचार्ज|^ic$)/i.test(person.role)?1:0,extra:0,female:null}}}depPersist();depRefreshList();return true}
function depNew(type='officer'){if(!DEP_TYPES[type])type='officer';depEl('depSearch').value='';depEl('depFilter').value='';depUndoPush();const u={id:'D-'+Date.now().toString(36),title:'New '+DEP_TYPES[type],type,position:null,ground:'',rotation:0,scale:1,enabled:true,speed:7,route:[],routeMode:'pingpong',personnel:[],notes:'User-added duty / object',shifts:{day:{force:type==='officer'?1:null,incharge:null,extra:0,female:null},night:{force:type==='officer'?1:null,incharge:null,extra:0,female:null}}};depUnits.push(u);depSelected=u.id;depPersist();depRefreshList();depEditor()}
