function depOfficerModelHit(x,y){if(!depVisible||conceptMode||depTypeHidden.has('officer')||(depMode&&depMode!=='addPoint'))return null;const ray=depScreenRay(x,y);if(!ray)return null;let best=null;for(const row of depExtraOfficers.values()){if(row.layer&&hidden.has(row.layer))continue;const lo=[row.p[0]-.95,row.p[1]-.1,row.p[2]-.95],hi=[row.p[0]+.95,row.p[1]+3.9,row.p[2]+.95];let near=0,far=Infinity;for(let i=0;i<3;i++){if(Math.abs(ray.direction[i])<1e-8){if(ray.origin[i]<lo[i]||ray.origin[i]>hi[i]){far=-1;break}}else{let a=(lo[i]-ray.origin[i])/ray.direction[i],b=(hi[i]-ray.origin[i])/ray.direction[i];if(a>b)[a,b]=[b,a];near=Math.max(near,a);far=Math.min(far,b)}}if(far>=near&&near>0&&(!best||near<best.distance))best={row,distance:near}}return best}
