function depSmoothHeading(current,next,dt){if(!Number.isFinite(current))return next;const delta=Math.atan2(Math.sin(next-current),Math.cos(next-current));return current+delta*(1-Math.exp(-9*Math.max(.001,dt)))}
function depVehicleShot(pose,type,mode,offset=0,pitch=0,chase=18,scale=1){const a=pose.angle+offset,fx=Math.sin(a),fz=Math.cos(a),p=pose.p;let eye,at;if(mode==='fpv'){eye=[p[0]+Math.sin(pose.angle)*1.2*scale,p[1]+(type==='rider'?3.45:3.35)*scale,p[2]+Math.cos(pose.angle)*1.2*scale];at=[eye[0]+fx*Math.cos(pitch)*24,eye[1]+Math.sin(pitch)*24,eye[2]+fz*Math.cos(pitch)*24]}else{eye=[p[0]-fx*chase*scale,p[1]+((type==='machan'?16.5:8.5)+pitch*10)*scale,p[2]-fz*chase*scale];at=[p[0]+Math.sin(pose.angle)*2*scale,p[1]+(type==='machan'?6:2.4)*scale,p[2]+Math.cos(pose.angle)*2*scale]}return{eye,at}}
function depEnterVehicleView(id,mode='third'){const wasFollowing=!!depFollowState;const u=depUnits.find(v=>v.id===id);if(!u||!u.position||mode==='fpv'&&!['rider','qrt','patrol','ambulance','fire'].includes(u.type))return;depFinishManualControl();resetNavigationKeys();const previous=depFollowState?.previous||{target:[...target],yaw,elevation,distance,topView};if(depFollowState){depFollowState.id=u.id;depFollowState.mode=mode;depFollowState.offset=0;depFollowState.pitch=0;depFollowState.fov=1;depVehicleCamera=null}else{exitNavigation();setConcept(false);depFollowState={id:u.id,mode,offset:0,pitch:0,chase:18,fov:1,previous};depVehicleCamera=null}depPanel.hidden=true;depDutyCard.hidden=true;depChoose.hidden=true;depReview.hidden=true;depMode=null;depRoutebar.hidden=true;depFollowHud.hidden=false;pandalInterior=false;topView=false;anim=null;orbit=false;depAnimate=true;depEl('depAnimate').checked=true;if(!wasFollowing&&depPausedRoutes.has(u.id))depToggleMotion(u);sceneEl.classList.add('vehicle-follow');resize();depFollowTick(1);dirty=true;canvas.focus({preventScroll:true});sceneEl.scrollIntoView({block:'start'})}
function depExitVehicleView(restore=true){if(!depFollowState)return;depFinishManualControl();resetNavigationKeys();depDutyCard.hidden=true;const old=depFollowState.previous;depFollowState=null;depVehicleCamera=null;depFollowHud.hidden=true;sceneEl.classList.remove('vehicle-follow');resize();if(restore&&old){target=[...old.target];yaw=old.yaw;elevation=old.elevation;distance=old.distance;topView=old.topView}dirty=true}
function depFollowTick(dt){const state=depFollowState;if(!state)return;const u=depUnits.find(v=>v.id===state.id);if(!u||!u.enabled||!u.position){depExitVehicleView();return}const pose=depPose(u);state.heading=depSmoothHeading(state.heading,pose.angle,dt);const shot=depVehicleShot({...pose,angle:state.heading},u.type,state.mode,state.offset,state.pitch,state.chase,u.scale),blend=1-Math.exp(-12*Math.max(.001,dt));if(!depVehicleCamera)depVehicleCamera=shot;else for(const key of ['eye','at'])depVehicleCamera[key]=depVehicleCamera[key].map((v,i)=>v+(shot[key][i]-v)*blend);target=[...pose.p];target[1]+=2.4;const paused=depPausedRoutes.has(u.id),moving=u.route.length>1;depEl('depVehicleViewTitle').textContent=u.title+' · '+(state.mode==='fpv'?'FPV':'Third person')+' · '+(state.manual?'Keyboard control':!moving?'No route':paused?'Paused':'Moving');depEl('depViewMotion').textContent=paused?'Resume':'Pause';depEl('depViewMotion').disabled=!moving;depEl('depViewFPV').hidden=!['rider','qrt','patrol','ambulance','fire'].includes(u.type);depEl('depViewSave').hidden=!state.manual;depEl('depViewFPV').setAttribute('aria-pressed',String(state.mode==='fpv'));depEl('depViewThird').setAttribute('aria-pressed',String(state.mode==='third'));dirty=true}
function depFollowLook(dx,dy){if(!depFollowState)return;depFollowState.offset-=dx*.005;depFollowState.pitch=Math.max(depFollowState.mode==='fpv'?-.65:-.4,Math.min(.65,depFollowState.pitch-dy*.004));dirty=true}
function depFollowZoom(k){if(!depFollowState)return;if(depFollowState.mode==='fpv')depFollowState.fov=Math.max(.55,Math.min(1.35,depFollowState.fov*k));else depFollowState.chase=Math.max(9,Math.min(45,depFollowState.chase*k));dirty=true}
depEl('depViewFPV').onclick=()=>depEnterVehicleView(depFollowState.id,'fpv');depEl('depViewThird').onclick=()=>depEnterVehicleView(depFollowState.id,'third');depEl('depViewExit').onclick=()=>depExitVehicleView();depEl('depViewMotion').onclick=()=>{const u=depUnits.find(v=>v.id===depFollowState.id);if(u){depFinishManualControl();depToggleMotion(u)}depFollowTick(.05)};depEl('depViewReset').onclick=()=>{depFollowState.offset=0;depFollowState.pitch=0;depFollowState.chase=18;depFollowState.fov=1;depVehicleCamera=null;dirty=true};


// Manual deployment placement shares the existing third-person camera and roster.
function depEnterObjectControl(id){
 const u=depUnits.find(v=>v.id===id);if(!u?.position)return;
 const pose=depPose(u);
 depEnterVehicleView(id,'third');
 if(!depFollowState)return;
 if(u.route.length>1&&!depPausedRoutes.has(id))depPausedRoutes.set(id,depTime);
 depFollowState.manual={p:[...pose.p],angle:pose.angle,changed:false,undo:false,idle:0,jump:{height:0,velocity:0}};
 depFollowState.heading=pose.angle;depFollowState.chase=u.type==='machan'?27:18;
 depVehicleCamera=null;depFollowTick(1);dirty=true;
}
function depManualJump(){const m=depFollowState?.manual;if(!m)return;if(!m.jump)m.jump={height:0,velocity:0};if(m.jump.height<.001&&m.jump.velocity===0){m.jump.velocity=11;dirty=true}}
function depManualTick(dt,v){
 const state=depFollowState,m=state?.manual,u=depUnits.find(v=>v.id===state?.id);if(!m||!u)return;
 if(m.jump&&(m.jump.velocity||m.jump.height)){const j=m.jump;j.height+=j.velocity*dt-10*dt*dt;j.velocity-=20*dt;if(j.height<=0){j.height=0;j.velocity=0}dirty=true;canvas.dataset.objectJump=String(j.height)}
 const moving=Math.abs(v.forward)+Math.abs(v.side)+Math.abs(v.turn)>.001;
 if(!moving){if(m.changed){m.idle+=dt;if(m.idle>.35){depPersist();m.changed=false;depEl('depVehicleViewTitle').textContent=u.title+' · Third person · Position saved'}}return}
 if(!m.undo){depUndoPush();m.undo=true}
 const angleDelta=-v.turn*1.15*dt;
 if(angleDelta){
  const c=Math.cos(angleDelta),s=Math.sin(angleDelta),pivot=m.p;
  const rotate=p=>{const x=p[0]-pivot[0],z=p[2]-pivot[2];return[pivot[0]+x*c+z*s,p[1],pivot[2]-x*s+z*c]};
  u.position=rotate(u.position);u.route=u.route.map(rotate);u.rotation+=angleDelta;m.angle+=angleDelta;
 }
 const speed=(u.type==='rider'||u.type==='patrol'||u.type==='qrt'?10:5)*(heldKeys.has('shift')?2:1);
 const dx=(Math.sin(m.angle)*v.forward-Math.cos(m.angle)*v.side)*speed*dt;
 const dz=(Math.cos(m.angle)*v.forward+Math.sin(m.angle)*v.side)*speed*dt;
 depMoveUnit(u,[u.position[0]+dx,u.position[1],u.position[2]+dz]);m.p[0]+=dx;m.p[2]+=dz;
 m.changed=true;m.idle=0;dirty=true;
 canvas.dataset.controlledObject=JSON.stringify({id:u.id,position:m.p.map(n=>+n.toFixed(4)),rotation:+m.angle.toFixed(5)});
}
function depFinishManualControl(){
 const state=depFollowState,m=state?.manual;if(!m)return;
 if(m.changed)depPersist();
 state.manual=null;
}
