function depPointOptions(p,x,y){depPanel.hidden=true;depChoose.replaceChildren();const title=document.createElement('b');title.textContent='What to deploy here?';depChoose.append(title);const grid=document.createElement('div');grid.className='dep-quick';for(const type of ['officer','barricade','naka','machan','morcha','qrt','rider','patrol','ambulance','fire']){const b=document.createElement('button');b.style.cssText='padding:9px;border:1px solid #bdcbbd;border-radius:6px;background:#f5f4e9;color:#244b54;cursor:pointer';b.innerHTML=depMapIcon(type)+' '+DEP_TYPES[type];b.onclick=()=>depCreateAtPoint(type,p);grid.append(b)}depChoose.append(grid);const close=document.createElement('button');close.textContent='Choose another place';close.onclick=()=>{depChoose.hidden=true};depChoose.append(close);depChoose.style.left=Math.max(12,Math.min(window.innerWidth-315,x+12))+'px';depChoose.style.top=Math.max(80,Math.min(window.innerHeight-370,y-70))+'px';depChoose.hidden=false}
function depCreateAtPoint(type,p){depChoose.hidden=true;depFlow={before:depClone(depUnits),undoLength:depUndoStack.length,id:null};depMode=null;depNew(type);const u=depUnits.find(v=>v.id===depSelected);depFlow.id=u.id;u.position=depRoadPoint(p,false);depDirty=true;depPanel.hidden=true;if(['qrt','patrol','rider','ambulance','fire'].includes(type)){depBeginPick('route');depDraftRoute=[[...u.position]];depEl('depPickText').textContent='Starting point set · click the path, then Preview movement';depEl('depFinishRoute').textContent='Preview movement';depEl('depCancelPick').textContent='Cancel draft'}else depReviewDraft();dirty=true}
